package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidAddressException;

/**
 * Normalizes the owner's postal address in place (trim and collapse whitespace,
 * upper-case, expand common abbreviations) and rejects an address that is blank once
 * normalized. Runs before the household steps so duplicate detection and the shared
 * household id compare the normalized form.
 */
public class NormalizeOwnerAddress {

    public void service(@Val Owner owner) throws InvalidAddressException {
        String normalized = OwnerAddresses.normalize(owner.getAddress());
        if (normalized.isBlank()) {
            throw new InvalidAddressException("Address must not be blank");
        }
        owner.setAddress(normalized);
    }
}
===== OwnerAddresses =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * The single-sourced definition of a normalized postal address, shared by the
 * create-time {@link NormalizeOwnerAddress} step (which stores the normalized value)
 * and {@link HouseholdKey} (so every address comparison uses the same normalized form).
 *
 * <p>Normalization trims the value, collapses any run of whitespace to a single space,
 * upper-cases it and expands common street-type abbreviations ({@code ST} &rarr;
 * {@code STREET}, {@code RD} &rarr; {@code ROAD}, {@code AVE} &rarr; {@code AVENUE}).
 */
final class OwnerAddresses {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private OwnerAddresses() {
    }

    /**
     * Normalize an address. Returns {@code ""} when {@code address} is {@code null} or
     * is blank once whitespace has been trimmed and collapsed.
     */
    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}
===== ValidatePostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the owner's postcode WHEN PRESENT, rejecting with 400 via
 * {@link InvalidPostcodeException} when it is not valid for the owner's city.
 *
 * <p>Rules: an absent (null/blank) postcode is accepted (optional, backward
 * compatible). When present it must be a 4-digit value. For a city with a known
 * region it must fall within that region's inclusive postcode range; a city with no
 * known region accepts any 4-digit postcode.
 */
public class ValidatePostcode {

    /** Fixed city-to-region table, keyed by city name. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region-to-inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    public void service(@Val Owner owner) throws InvalidPostcodeException {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException("Postcode must be a 4-digit value");
        }
        String region = CITY_REGION.get(owner.getCity());
        if (region == null) {
            return; // a city with no known region accepts any 4-digit postcode
        }
        int[] range = REGION_POSTCODES.get(region);
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException("Postcode '" + postcode + "' is not valid for city '"
                    + owner.getCity() + "' (region " + region + " expects " + range[0] + "-" + range[1] + ")");
        }
    }
}
